from pathlib import Path
import re

path=Path('index.html')
text=path.read_text(encoding='utf-8')

text=text.replace('Prototype 0.5','Prototype 0.6')
text=text.replace('id="versionLabel">0.5<','id="versionLabel">0.6<')
text=text.replace("const APP_VERSION='0.5';","const APP_VERSION='0.6';")

helpers=r'''function perimeterPath(t,width,depth,margin=.12){const x0=-width/2+margin,x1=width/2-margin,z0=-depth/2+margin,z1=depth/2-margin,segments=[{ax:x0,az:z0,bx:x1,bz:z0},{ax:x1,az:z0,bx:x1,bz:z1},{ax:x1,az:z1,bx:x0,bz:z1},{ax:x0,az:z1,bx:x0,bz:z0}],lens=segments.map(s=>Math.hypot(s.bx-s.ax,s.bz-s.az)),total=lens.reduce((a,b)=>a+b,0);let dist=Math.max(0,Math.min(.9999,t))*total;for(let i=0;i<segments.length;i++){if(dist<=lens[i]){const s=segments[i],f=lens[i]?dist/lens[i]:0;return{x:THREE.MathUtils.lerp(s.ax,s.bx,f),z:THREE.MathUtils.lerp(s.az,s.bz,f),angle:Math.atan2(s.bz-s.az,s.bx-s.ax)}}dist-=lens[i]}return{x:x0,z:z0,angle:0}}
function rasterPath(t,width,depth,rows=6,margin=.12){const x0=-width/2+margin,x1=width/2-margin,z0=-depth/2+margin,z1=depth/2-margin,totalRows=Math.max(1,rows),rowFloat=Math.max(0,Math.min(.9999,t))*totalRows,row=Math.min(totalRows-1,Math.floor(rowFloat)),f=rowFloat-row,z=totalRows===1?0:THREE.MathUtils.lerp(z0,z1,row/(totalRows-1)),forward=row%2===0;return{x:forward?THREE.MathUtils.lerp(x0,x1,f):THREE.MathUtils.lerp(x1,x0,f),z,angle:forward?0:Math.PI}}
'''
if 'function perimeterPath(' not in text:
    text=text.replace('function spawnParticle(',helpers+'function spawnParticle(',1)

text=re.sub(r"function startPrint\(\)\{.*?\}function completePrint\(\)","function startPrint(){if(state!=='idle')return;progress=0;state='printing';printStart=performance.now();completeAt=0;clipPlane.constant=baseY;layerPlane.visible=true;extrusionLine.visible=true;nozzleGlow.intensity=4.8;ui.small.textContent='POSITIONING NOZZLE';ui.big.textContent='';ui.bar.style.width='0%';hotZone.material.opacity=.38;hotZone.scale.set(1.24,1.24,1.24);resetParticles();updateUI()}function completePrint()",text,count=1,flags=re.S)

animate=r'''function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-prev)/1000);prev=now;if(state==='printing'){progress=Math.min(1,(now-printStart)/getDuration());const bounds=selected.bounds;let x=0,z=0,angle=0,printHeight=baseY,bedTravel=0,spawnChance=.35;if(progress<.07){const prep=progress/.07,target=perimeterPath(0,bounds.x,bounds.z,.1);x=THREE.MathUtils.lerp(1.2,target.x,prep);z=THREE.MathUtils.lerp(.84,target.z,prep);angle=target.angle;printHeight=baseY;ui.small.textContent='POSITIONING NOZZLE';ui.big.textContent='';layerPlane.material.opacity=.18+.18*prep;hotZone.scale.set(1.28,1.28,1);spawnChance=.08}else if(progress<.24){const t=(progress-.07)/.17,path=t<.7?perimeterPath(t/.7,bounds.x,bounds.z,.1):rasterPath((t-.7)/.3,bounds.x,bounds.z,5,.13);x=path.x;z=path.z;angle=path.angle;printHeight=baseY+selected.height*(.055*t);ui.small.textContent='LAYING FIRST LAYER';ui.big.textContent=Math.round(progress*100)+'%';layerPlane.material.opacity=.5-.16*t;hotZone.scale.set(1.32,1.32,1);spawnChance=.62}else if(progress<.9){const t=(progress-.24)/.66,totalLayers=28,layerFloat=t*totalLayers,layerIndex=Math.min(totalLayers-1,Math.floor(layerFloat)),within=layerFloat-layerIndex,path=rasterPath(within,bounds.x,bounds.z,7,.13),layerBase=selected.height*.08,layerSpan=selected.height*.84,layerHeight=layerSpan/totalLayers;x=path.x;z=path.z;angle=path.angle;printHeight=baseY+layerBase+layerHeight*layerIndex+layerHeight*within*.22;ui.small.textContent='PRINTING LAYERS';ui.big.textContent=Math.round(progress*100)+'%';layerPlane.material.opacity=.22+.08*Math.sin(now*.024);hotZone.scale.set(.9,.9,1);bedTravel=Math.sin(t*Math.PI*8)*.034;spawnChance=.44}else{const t=(progress-.9)/.1,path=t<.62?perimeterPath(t/.62,bounds.x*.9,bounds.z*.9,.11):rasterPath((t-.62)/.38,bounds.x*.78,bounds.z*.78,4,.14);x=path.x;z=path.z;angle=path.angle;printHeight=baseY+selected.height*(.92+.08*t);ui.small.textContent='FINAL LAYERS';ui.big.textContent=Math.round(progress*100)+'%';layerPlane.material.opacity=.34+.12*Math.sin(now*.03);hotZone.scale.set(1.02,1.02,1);spawnChance=.56}clipPlane.constant=printHeight;headGroup.position.set(x,printHeight+.58,z+.06);xGantry.position.y=printHeight+.75;bedCarrier.position.z=bedTravel;layerPlane.visible=true;layerPlane.position.set(0,printHeight+.004,.06+bedTravel);layerPlane.scale.set(bounds.x/1.55,bounds.z/.9,1);extrusionLine.visible=true;extrusionLine.position.set(x,printHeight+.012,z+.06+bedTravel);extrusionLine.scale.set(progress<.24?1.65:progress>.9?1.25:1,1,1);extrusionLine.rotation.y=angle;ui.bar.style.width=Math.round(progress*100)+'%';nozzleGlow.intensity=2.4+.85*Math.sin(now*.028);hotZone.material.opacity=.16+.11*Math.sin(now*.02);hotZone.position.set(x,.712,z+.06+bedTravel);workGlow.material.opacity=.08+.05*Math.sin(now*.005);spool.rotation.x+=dt*(2.5+saveData.speed*.55+(progress<.24?.35:0));if(Math.random()<spawnChance)spawnParticle(x,printHeight+.045,z+.06+bedTravel);particles.forEach(p=>{if(p.life>0){p.life-=dt;p.mesh.visible=true;p.mesh.position.x+=p.dx;p.mesh.position.y+=p.dy*dt*4.7;p.mesh.position.z+=p.dz;p.mesh.material.opacity=Math.max(0,p.life*3.4);if(p.life<=0){p.mesh.visible=false;p.mesh.material.opacity=0}}});if(progress>=1)completePrint()}else{ui.bar.style.width=state==='complete'?'100%':'0%';bedCarrier.position.z+=(0-bedCarrier.position.z)*Math.min(1,dt*3.4);xGantry.position.y+=(2.48-xGantry.position.y)*Math.min(1,dt*3.2);headGroup.position.x+=(1.2-headGroup.position.x)*Math.min(1,dt*3.6);headGroup.position.y+=(2.96-headGroup.position.y)*Math.min(1,dt*3.6);headGroup.position.z+=(.84-headGroup.position.z)*Math.min(1,dt*3.6);layerPlane.visible=false;extrusionLine.visible=false;hotZone.material.opacity*=.88;workGlow.material.opacity=.11;particles.forEach(p=>{if(p.life>0){p.life-=dt;p.mesh.position.y+=p.dy*dt*4.5;p.mesh.material.opacity=Math.max(0,p.life*3.2)}else p.mesh.visible=false});if(state==='complete')modelMeshes[selected.id].group.rotation.y=Math.sin((now-completeAt)*.001)*.18;else modelMeshes[selected.id].group.rotation.y*=.9}accentMat.emissiveIntensity=state==='printing'?.58:.34;screenMat.emissiveIntensity=.35+.15*Math.sin(now*.0022);bedSpot.intensity=state==='printing'?1.9:1.6;const zoom=state==='complete'?1:0,targetX=5.95-zoom*.55,targetY=4.1-zoom*.22,targetZ=7.85-zoom*.78;camera.position.x+=(targetX-camera.position.x)*Math.min(1,dt*2.4);camera.position.y+=(targetY-camera.position.y)*Math.min(1,dt*2.4);camera.position.z+=(targetZ-camera.position.z)*Math.min(1,dt*2.4);camera.lookAt(0,1.32,0);renderer.render(scene,camera)}'''
text,n=re.subn(r"function animate\(now\)\{.*?\}requestAnimationFrame\(animate\);addEventListener",animate+"requestAnimationFrame(animate);addEventListener",text,count=1,flags=re.S)
if n!=1:
    raise SystemExit('Could not replace animate() block')

path.write_text(text,encoding='utf-8')
Path('version.json').write_text('{\n  "version": "0.6"\n}\n',encoding='utf-8')
print('Prototype 0.6 applied')